[CmdletBinding()]
param([string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=(Get-Location).Path};$p=Join-Path ([IO.Path]::GetTempPath()) ('es-engineering-completion-'+[guid]::NewGuid().ToString('N')+'.json');try{$valid=[ordered]@{status='completed';evidenceSummary=[ordered]@{eligibleCount=2;independentReplayVerifiedCount=2;providerScoreComparisonStatus='stable'}};$valid|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 -LiteralPath $p;powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $ProjectRoot 'ES/Automation/ABCD/Test-ESABCEngineeringCompletionEvidence.ps1') -ResultPath $p|Out-Null;$validExit=$LASTEXITCODE;$forged=[ordered]@{status='completed';evidenceSummary=[ordered]@{eligibleCount=2;independentReplayVerifiedCount=0;providerScoreComparisonStatus='drift-failed'}};$forged|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 -LiteralPath $p;powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $ProjectRoot 'ES/Automation/ABCD/Test-ESABCEngineeringCompletionEvidence.ps1') -ResultPath $p|Out-Null;$forgedExit=$LASTEXITCODE;$pass=($validExit -eq 0 -and $forgedExit -ne 0);$state='failed';if($pass){$state='passed'};[pscustomobject]@{status=$state;validExit=$validExit;forgedExit=$forgedExit};if(-not $pass){exit 1}}finally{if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Force}}
